diff --git a/test.js b/test.js
index e303a46..18e5ba3 100644
--- a/test.js
+++ b/test.js
@@ -193,6 +193,37 @@ test('clearQueue', async t => {
 	t.is(limit.pendingCount, 0);
 });

+test('clearQueue with default options leaves the active promise untouched and clears every queued function', async t => {
+	const limit = pLimit(1);
+
+	let queuedRan = false;
+
+	const activePromise = limit(() => delay(100).then(() => 'active-result'));
+	const queuedPromise = limit(() => {
+		queuedRan = true;
+		return 'should-not-run';
+	});
+
+	await Promise.resolve();
+	t.is(limit.activeCount, 1);
+	t.is(limit.pendingCount, 1);
+
+	limit.clearQueue();
+
+	// The active promise is untouched: still running, not rejected or removed.
+	t.is(limit.activeCount, 1);
+	t.is(limit.pendingCount, 0);
+
+	t.is(await activePromise, 'active-result');
+
+	// The queued function was cleared and never invoked.
+	t.false(queuedRan);
+
+	// With default options (rejectOnClear: false), the queued promise never settles.
+	const raceResult = await Promise.race([queuedPromise, delay(50).then(() => 'timed-out')]);
+	t.is(raceResult, 'timed-out');
+});
+
 // Node.js 20 has a bug where DOMException is not properly handled by AVA's `throwsAsync`.
 const testClearQueueRejects = process.versions.node.startsWith('20.') ? test.skip : test;

